toolArgs.file_text:
.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel Sidebar */
.channel-sidebar {
    background: #2b2d31;
    color: #f2f3f5;
    padding: 1rem 0;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
}

.sidebar-title {
    padding: 0 1rem;
    margin: 0 0 0.75rem;
    font-size: 0.85rem;
    text-transform: uppercase;
    color: #949ba4;
    letter-spacing: 0.02em;
}

.channel-list {
    display: flex;
    flex-direction: column;
}

.channel-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 0.5rem;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #35373c;
}

.channel-item.active {
    background: #404249;
}

.channel-info {
    display: flex;
    flex-direction: column;
    gap: 2px;
    overflow: hidden;
}

.channel-name {
    font-weight: 500;
    font-size: 0.95rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-desc {
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    background: #f23f42;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 10px;
    padding: 2px 6px;
    min-width: 18px;
    text-align: center;
    flex-shrink: 0;
}

/* Message Area */
.message-area {
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #f2f3f5;
    overflow: hidden;
}

.channel-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

.channel-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

.channel-description {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    color: #949ba4;
    padding: 0.5rem;
    font-size: 0.85rem;
}

/* Message Bubble */
.message-bubble {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #f2f3f5;
}

.timestamp {
    font-size: 0.7rem;
    color: #949ba4;
}

.message-content {
    margin: 0.2rem 0 0;
    font-size: 0.9rem;
    line-height: 1.4;
    color: #dbdee1;
}

.reactions {
    display: flex;
    gap: 0.25rem;
    margin-top: 0.35rem;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: border-color 0.15s;
}

.reaction-badge:hover {
    border-color: #5865f2;
}

.thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0;
    margin-top: 0.25rem;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 2px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px;
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 3px;
    font-size: 0.9rem;
    transition: background 0.1s;
}

.action-btn:hover {
    background: #3f4147;
}

.emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 2px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 4px;
    z-index: 10;
}

.emoji-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-btn:hover {
    background: #3f4147;
}

/* Message Input */
.message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #3f4147;
    flex-shrink: 0;
}

.message-input textarea {
    flex: 1;
    resize: none;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 1rem;
    color: #f2f3f5;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
}

.message-input textarea::placeholder {
    color: #6d6f78;
}

.send-btn {
    background: #5865f2;
    color: white;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 1.2rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    align-self: flex-end;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    display: flex;
    flex-direction: column;
    background: #2b2d31;
    color: #f2f3f5;
    border-left: 1px solid #1e1f22;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    color: #949ba4;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background 0.1s, color 0.1s;
}

.close-btn:hover {
    background: #3f4147;
    color: #f2f3f5;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

.thread-root-message .author {
    font-size: 0.85rem;
}

.thread-root-message .content {
    margin: 0.25rem 0 0;
    font-size: 0.85rem;
    color: #dbdee1;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.thread-reply {
    padding: 0.4rem 0;
}

